  document.getElementById('addSheetTitle').textContent='Yeni Seri';
  ['seriesName','altNameInput','fansubInput','coverUrlInput','seriesNote','chapterTotal','autoIncrAmt'].forEach(id=>document.getElementById(id).value='');
